<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Créer une entreprise — {{ config('app.name') }}</title><link href="{{ asset('hub/assets/css/vendor.min.css') }}" rel="stylesheet">@include('partials.design-system-head')<link href="{{ asset('hub/assets/css/saas-shell.css') }}?v=20260903-13" rel="stylesheet"><link href="{{ asset('hub/assets/css/saas-pages.css') }}?v=20260902-16" rel="stylesheet"></head><body class="saas-body"><main class="saas-content saas-auth-content"><div class="saas-card saas-create-company-card"><a class="saas-btn saas-btn-ghost" href="{{ route('companies.select') }}"><i class="bi bi-arrow-left" aria-hidden="true"></i> Retour aux entreprises</a><div class="saas-page-heading"><div><span class="saas-eyebrow">Nouvel espace</span><h1>Créer une entreprise</h1><p>Renseignez les informations essentielles. Vous pourrez compléter la configuration plus tard.</p></div></div><div id="companyError" class="saas-alert saas-alert-danger" role="alert" hidden></div><form id="createCompanyForm" enctype="multipart/form-data"><input type="hidden" name="_token" value="{{ csrf_token() }}"><div class="saas-form-grid"><div class="saas-form-group"><label for="name">Nom de l’entreprise</label><input id="name" name="name" required autofocus></div><div class="saas-form-group"><label for="email">E-mail</label><input id="email" name="email" type="email" required></div><div class="saas-form-group"><label for="number1">Téléphone principal</label><input id="number1" name="number1" required></div><div class="saas-form-group"><label for="adress">Adresse</label><input id="adress" name="adress" required></div><div class="saas-form-group"><label for="default_tax">Taxe par défaut (%)</label><input id="default_tax" name="default_tax" type="number" min="0" max="100" step="0.01"><small>Facultatif, modifiable ensuite dans Comptabilité.</small></div><div class="saas-form-group"><label for="logo">Logo <span class="saas-help">Facultatif</span></label><input id="logo" name="logo" type="file" accept="image/*"></div><div class="saas-form-group saas-form-group-wide"><label for="description">Description E-commerce</label><textarea id="description" name="description" rows="4"></textarea></div></div><div class="saas-modal-actions"><a class="saas-btn saas-btn-ghost" href="{{ route('companies.select') }}">Annuler</a><button class="saas-btn saas-btn-primary" type="submit" data-loading-text="Création…"><i class="bi bi-check-lg" aria-hidden="true"></i> Créer l’entreprise</button></div></form></div></main><script src="{{ asset('hub/assets/js/vendor.min.js') }}"></script><script src="{{ asset('hub/assets/js/server-button-loader.js') }}?v=20260826-2"></script><script src="https://cdn.jsdelivr.net/npm/sweetalert2@10"></script><script>document.getElementById('createCompanyForm').addEventListener('submit',function(e){e.preventDefault();const form=this,b=form.querySelector('button[type=submit]');window.ServerButtonLoader.withLoader(b,fetch('{{ route('companies.store') }}',{method:'POST',body:new FormData(form),headers:{Accept:'application/json'}}).then(r=>r.json()).then(data=>{if(!data.status)throw new Error(data.msg||'Votre plan actuel ne permet pas de créer une nouvelle entreprise.');return Swal.fire({icon:'success',title:'Entreprise créée',text:'Voulez-vous l’ouvrir maintenant ?',showCancelButton:true,confirmButtonText:'Oui, ouvrir',cancelButtonText:'Rester ici'}).then(x=>x.isConfirmed?location.href=data.switch_url:location.href=data.selection_url)})).catch(err=>{const box=document.getElementById('companyError');box.hidden=false;box.textContent=err.message})});</script></body></html>
